import{c as e,Q as s,j as o,m as r}from"./chunks/framework.BqPkuuVc.js";const g=JSON.parse('{"title":"Status and race time rules","description":"","frontmatter":{},"headers":[],"relativePath":"user/reference/status-and-race-time.md","filePath":"user/reference/status-and-race-time.md"}'),a={name:"user/reference/status-and-race-time.md"};function n(i,t,h,d,l,c){return s(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="status-and-race-time-rules" tabindex="-1">Status and race time rules <a class="header-anchor" href="#status-and-race-time-rules" aria-label="Permalink to &quot;Status and race time rules&quot;">​</a></h1><p><strong>Audience:</strong> Event organisers and operators needing to understand why a competitor has the status or race time that Manager is showing.</p><p>Every competitor has a <strong>status</strong> (OK, MP, DNF, On Course, …) and, once they finish cleanly, a <strong>race time</strong>. Manager sets both for you as the day unfolds — a start time passes, a radio punch arrives, a card is downloaded — so most of the time you never touch them. This page explains the rules behind those automatic changes so that when a status looks wrong you know <em>why</em> Manager decided it, and which lever fixes it.</p><blockquote><p>Manager uses the term <strong>On Course</strong> in the UI for a competitor who has started but not yet finished. Other event systems call this <em>In Forest</em>. This page uses <strong>On Course</strong> throughout.</p></blockquote><h2 id="the-status-values" tabindex="-1">The status values <a class="header-anchor" href="#the-status-values" aria-label="Permalink to &quot;The status values&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Shown as</th><th>What it means</th></tr></thead><tbody><tr><td>None</td><td><em>(blank)</em></td><td>No result yet. Manager has no evidence the competitor has started or finished.</td></tr><tr><td>On Course</td><td><strong>On Course</strong></td><td>Has started but not yet finished — out on the course right now (or a no-show whose start time has passed; see below).</td></tr><tr><td>OK</td><td><strong>OK</strong></td><td>Finished with a valid result. Can be <strong>provisional</strong> (from a radio finish, before the card is read) or <strong>final</strong> (from the card download).</td></tr><tr><td>MissingPunch</td><td><strong>MP</strong></td><td>Card was downloaded but one or more required controls weren&#39;t punched.</td></tr><tr><td>DidNotFinish</td><td><strong>DNF</strong></td><td>Either the card was downloaded and had no finish punch, or a finish-station read accounted for them at the finish but with no card to validate. See <a href="#how-a-dnf-happens">How a DNF happens</a>.</td></tr><tr><td>DidNotStart</td><td><strong>DNS</strong></td><td>Never started.</td></tr><tr><td>Disqualified</td><td><strong>DSQ</strong></td><td>Disqualified by the operator.</td></tr><tr><td>Overtime</td><td><strong>OVT</strong></td><td>Still out when the <a href="#5-course-closure--the-time-everyone-has-to-be-back">course closure</a> passed, or an overtime call you made yourself.</td></tr><tr><td>OutOfCompetition</td><td><strong>OOC</strong></td><td>Has a valid time but isn&#39;t counted in the ranked results — e.g. a course tester or a runner from another class.</td></tr><tr><td>NoTiming</td><td><strong>NT</strong></td><td>Took part but with no electronic timing — e.g. a beginner without a card.</td></tr><tr><td>NotParticipating</td><td><strong>NP</strong></td><td>In the entry list but explicitly not running this event. Also set automatically if a card is evaluated for a competitor who has no class.</td></tr><tr><td>Cancelled</td><td><strong>CAN</strong></td><td>The entry was cancelled.</td></tr></tbody></table><h2 id="how-a-status-gets-set" tabindex="-1">How a status gets set <a class="header-anchor" href="#how-a-status-gets-set" aria-label="Permalink to &quot;How a status gets set&quot;">​</a></h2><p>Four things set status on their own, and you can always override the result by hand. They build on each other through the day — a start time passes (→ <strong>On Course</strong>), a radio finish arrives (→ provisional <strong>OK</strong>), then the card is read (→ final <strong>OK</strong> or <strong>MP</strong>).</p><h3 id="_1-the-clock-—-start-time-passes" tabindex="-1">1. The clock — start time passes <a class="header-anchor" href="#_1-the-clock-—-start-time-passes" aria-label="Permalink to &quot;1. The clock — start time passes&quot;">​</a></h3><p>A background timer runs every few seconds. When a competitor with status <em>None</em> has an allocated start time and that time passes, Manager moves them to <strong>On Course</strong> — even with no radio start punch. This is deliberate: people show as out on the course even at events with no start radio.</p><blockquote><p><strong>Important:</strong> because a passed start time alone is enough, your <strong>On Course</strong> list at the end of the day normally includes every <em>no-show</em> who had a start time but never turned up. They aren&#39;t a safety problem, but you can&#39;t tell them apart from genuinely missing runners just by looking — clearing them with a DNS sweep is what makes the list meaningful. See <a href="./../running-the-event/safety-check">Safety check</a>.</p></blockquote><h3 id="_2-radio-punches" tabindex="-1">2. Radio punches <a class="header-anchor" href="#_2-radio-punches" aria-label="Permalink to &quot;2. Radio punches&quot;">​</a></h3><p>Where radio controls are in use, punches drive status as they arrive:</p><ul><li>A <strong>start</strong> punch moves a <em>None</em> competitor to <strong>On Course</strong> and records a punched start — which becomes their start time unless the <a href="./../event-setup/start-times#punched-starts">punching-start override</a> keeps an allocated time instead.</li><li>A <strong>normal control</strong> or <strong>check</strong> punch also moves them to <strong>On Course</strong> — Manager now knows they&#39;re physically out there, even if it missed the start.</li><li>A <strong>finish</strong> punch moves a <em>None</em> or <em>On Course</em> competitor to a <strong>provisional OK</strong> with a race time (see <a href="#provisional-vs-final-ok">Provisional vs final OK</a>).</li><li>Once a competitor has a <strong>final</strong> result, radio punches no longer change their status or start time.</li></ul><h3 id="_3-card-download-—-the-authoritative-result" tabindex="-1">3. Card download — the authoritative result <a class="header-anchor" href="#_3-card-download-—-the-authoritative-result" aria-label="Permalink to &quot;3. Card download — the authoritative result&quot;">​</a></h3><p>When a card is downloaded and assigned to a competitor, its punches are evaluated against the competitor&#39;s course. This is the <strong>authoritative</strong> result and replaces any provisional one:</p><ol><li><strong>No finish punch on the card</strong> → <strong>DNF</strong>.</li><li><strong>All required controls punched</strong> → <strong>OK</strong>, with a race time. Extra punches that aren&#39;t part of the course are ignored.</li><li><strong>One or more required controls missing</strong> → <strong>MP</strong> (no race time).</li><li><strong>Competitor has no class</strong> → <strong>NP</strong>.</li></ol><p>If the class has a pool of several courses, the card is checked against each: the first course that produces a clean <strong>OK</strong> wins. If none is clean, Manager keeps the best near-miss (an <strong>MP</strong> is preferred over a <strong>DNF</strong>, and among MPs the one with the fewest missing controls).</p><p>Manager re-evaluates the download automatically when something relevant changes — the competitor&#39;s class, the class&#39;s course assignment, or the course&#39;s control list. There&#39;s no separate recalculate step.</p><blockquote><p><strong>Unassigning a download</strong> clears the competitor&#39;s result back to <em>None</em> (status, time and splits reset). The start time is kept, since it may have come from the start list rather than the card.</p></blockquote><h3 id="_4-operator-overrides" tabindex="-1">4. Operator overrides <a class="header-anchor" href="#_4-operator-overrides" aria-label="Permalink to &quot;4. Operator overrides&quot;">​</a></h3><p>You can set a status by hand on the competitor&#39;s <strong>Result</strong> tab, and bulk-set no-shows to <strong>DNS</strong> from the Competitors list. Two rules protect real data:</p><ul><li><strong>You can&#39;t force OK.</strong> OK always needs a race time, and Manager re-checks it against the punches — set OK on someone still missing a control and it&#39;s corrected straight back to <strong>MP</strong>. To turn a genuine MP or DNF into OK, fix the underlying punches on the <strong>Overrides</strong> tab and the result follows.</li><li><strong>You can&#39;t reset to None while there&#39;s evidence they took part</strong> — a race time, a downloaded card, a start/finish/check punch, or radio punches. Manager tells you which evidence is blocking the reset so a genuine result is never erased by relabelling. (An allocated start time alone doesn&#39;t count as evidence — a no-show auto-flagged On Course can still be set to DNS.)</li></ul><p>Reading a control unit&#39;s backup memory also changes status — a start or check station read promotes a <em>None</em> competitor to <strong>On Course</strong>, and a finish station read marks an <em>On Course</em> competitor <strong>DNF</strong> (see <a href="#how-a-dnf-happens">How a DNF happens</a>). See <a href="./../running-the-event/station-memory">Station Memory</a> and <a href="./../running-the-event/safety-check#reading-sportident-stations">Safety check</a>.</p><h3 id="_5-course-closure-—-the-time-everyone-has-to-be-back" tabindex="-1">5. Course closure — the time everyone has to be back <a class="header-anchor" href="#_5-course-closure-—-the-time-everyone-has-to-be-back" aria-label="Permalink to &quot;5. Course closure — the time everyone has to be back&quot;">​</a></h3><p>An event can declare a <strong>course closure</strong>: the time of day by which every competitor must be back (<strong>Edit event → Details → Course closure</strong>; off unless you set it). It is a time of day, not a time limit — it says when the courses shut, not how long anyone had.</p><p>Once that time passes, the same background timer settles whoever nobody has accounted for:</p><ul><li><strong>On Course</strong> → <strong>Overtime</strong>. (A relay runner still waiting in the changeover pen becomes <strong>DNS</strong> instead — they were never handed the map.)</li><li><em>None</em> → <strong>DNS</strong>.</li><li>Provisional <strong><code>OK*</code></strong> → <strong>DNF</strong>, keeping the time and the <code>*</code> so the card is still chased.</li></ul><p>It leaves any status you set by hand alone.</p><p><strong>A card downloaded afterwards is scored Overtime too.</strong> A clean run whose <em>finish punch</em> landed at or after the closure gets <strong>Overtime</strong> instead of <strong>OK</strong>, keeping its time — the runner got round, just not by the time you set. Only OK is affected: a mis-punch stays <strong>MP</strong>. It is worked out from the finish punch&#39;s time of day, not from how long the runner took, so it is not a time limit. And it is derived, so it is reversible: correct a mis-typed closure and everyone is re-scored, or set a competitor back to <strong>OK</strong> by hand and your ruling sticks.</p><p><strong>Overtime does not mean &quot;accounted for&quot;.</strong> A runner marked Overtime with no time and no finish behind them is somebody nobody has seen, so they stay on the <strong>On Course</strong> list and in the on-course counts until something says they are back: a race time, a radio finish punch, a downloaded card, or a finish read out of the station&#39;s memory. That is true whether the clock marked them or you did. See <a href="./../running-the-event/safety-check#course-closure-settling-the-list-at-a-set-time">Safety check</a>.</p><h2 id="how-a-dnf-happens" tabindex="-1">How a DNF happens <a class="header-anchor" href="#how-a-dnf-happens" aria-label="Permalink to &quot;How a DNF happens&quot;">​</a></h2><p><strong>DNF</strong> lands on a competitor two different ways, and they mean slightly different things:</p><ul><li><strong>From the card download.</strong> The card was read and evaluated, but it had <strong>no finish punch</strong> — they genuinely didn&#39;t record a finish. This is the literal &quot;did not finish&quot;.</li><li><strong>From a finish-station read.</strong> This is the one that surprises people: punching the finish <em>is</em> a finish, so why DNF? Because reading the finish unit&#39;s backup memory tells Manager only <strong>that</strong> a card crossed the finish — it carries no course splits, so there&#39;s nothing to check the run against and Manager can&#39;t award an <strong>OK</strong>. It records <strong>DNF</strong> as a deliberate &quot;safe but unverified&quot; state: the competitor is accounted for (they came back, so they drop off the <strong>On Course</strong> list and out of the safety count) but they don&#39;t yet have a validated result.</li></ul><p>So a DNF from a finish-station read is really <em>&quot;returned, not yet verified&quot;</em> rather than <em>&quot;didn&#39;t finish&quot;</em>. <strong>Download their card to turn it into the real result</strong> — OK, MP, or a genuine DNF. Manager only does this to someone who was <strong>On Course</strong>: it won&#39;t DNF a competitor who never started (status <em>None</em>), and it leaves an already-final result (a real OK/MP/etc.) untouched.</p><h2 id="provisional-vs-final-ok" tabindex="-1">Provisional vs final OK <a class="header-anchor" href="#provisional-vs-final-ok" aria-label="Permalink to &quot;Provisional vs final OK&quot;">​</a></h2><p>A competitor can be <strong>OK</strong> in two ways:</p><table tabindex="0"><thead><tr><th></th><th>Provisional OK</th><th>Final OK</th></tr></thead><tbody><tr><td>Comes from</td><td>A radio <strong>finish</strong> punch</td><td>The <strong>card download</strong> (or a manual override)</td></tr><tr><td>Race time</td><td>Yes</td><td>Yes</td></tr><tr><td>Position</td><td>Assigned, but may still change</td><td>Final once no one left can beat it</td></tr><tr><td>On leaderboards</td><td>Time shown with a <code>*</code>, in italics, <strong>no medals</strong></td><td>Shown normally, with medals</td></tr><tr><td>On the <strong>Results</strong> screen</td><td>Hidden unless you tick <strong>Provisional results</strong> (off by default); then shown with a <code>*</code>, and carried into the PDF/print that mirrors the screen</td><td>Always shown</td></tr><tr><td>In an exported or uploaded results file (IOF XML, Eventor)</td><td>Included, but <strong>overridden to DNF</strong> — no time, finish time or place (see <a href="#what-an-exported-results-file-contains">What an exported results file contains</a>)</td><td>Included as the real result</td></tr><tr><td>In a live results feed</td><td>Included with its time — showing finishers before their card is read is the point of a live feed</td><td>Included</td></tr></tbody></table><p>A provisional OK means the competitor crossed a radio finish and has a time and a position, but the result isn&#39;t confirmed until the card is read. When the card is downloaded, Manager recalculates everything from the card (the authoritative source): the status may become <strong>OK</strong>, <strong>MP</strong> or <strong>DNF</strong>, the race time and start time are taken from the card, and the result becomes final.</p><h2 id="what-an-exported-results-file-contains" tabindex="-1">What an exported results file contains <a class="header-anchor" href="#what-an-exported-results-file-contains" aria-label="Permalink to &quot;What an exported results file contains&quot;">​</a></h2><p><strong>Publish → Export IOF XML</strong> and <strong>Publish → Upload to Eventor</strong> produce the <em>official</em> results file, and an official file has to say what became of <strong>everyone who took part</strong>. Leaving a competitor out doesn&#39;t hide the uncertainty — it tells the federation they never entered, which is a bigger claim than anything the omission was avoiding. So anyone whose result can&#39;t be stood behind goes in at the status that can be:</p><table tabindex="0"><thead><tr><th>On your screen</th><th>In the file</th><th>Time in the file?</th></tr></thead><tbody><tr><td><strong>OK</strong> (card downloaded)</td><td>OK</td><td>Yes</td></tr><tr><td><strong>OK*</strong> (radio finish, card not read)</td><td><strong>DNF</strong></td><td>No — no time, finish time, place or splits</td></tr><tr><td><strong>On Course</strong> (still out)</td><td><strong>DNF</strong></td><td>No</td></tr><tr><td><strong>MP</strong>, <strong>DNF</strong>, <strong>DSQ</strong>, <strong>OT</strong></td><td>the same status</td><td>As it stands</td></tr><tr><td><strong>OOC</strong>, <strong>No timing</strong></td><td>Not competing</td><td>Yes</td></tr><tr><td><strong>NP</strong></td><td>Did not enter</td><td>No</td></tr><tr><td><strong>Cancelled</strong></td><td>Cancelled</td><td>No</td></tr><tr><td><strong>DNS</strong></td><td>DNS</td><td>No</td></tr><tr><td><strong>No status</strong></td><td>DNS</td><td>No</td></tr></tbody></table><p>You get one choice over this, in the Publish dialog: <strong>whether non-starters go in</strong>. Turning it off drops both the competitors you marked <strong>DNS</strong> <em>and</em> the ones with <strong>no status</strong> — those export as DNS too, so leaving them in would defeat the point.</p><p>The Results screen&#39;s other <strong>INCLUDE</strong> toggles (On Course, No status, Provisional) only change what <em>you</em> see on screen. They don&#39;t change the exported file, so it doesn&#39;t matter what&#39;s ticked when you publish.</p><blockquote><p>A <strong>live</strong> results feed is different: it shows on-course runners as active and provisional finishers with their times, because showing the race as it happens is what it&#39;s for.</p></blockquote><h2 id="how-race-time-is-calculated" tabindex="-1">How race time is calculated <a class="header-anchor" href="#how-race-time-is-calculated" aria-label="Permalink to &quot;How race time is calculated&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Race time = Finish time − Start time</span></span></code></pre></div><p>Only a competitor who is <strong>OK</strong> <em>and</em> has a positive race time is ranked in results. Any other status — MP, DNF, DNS and the rest — carries no race time.</p><p>A competitor&#39;s start time comes from one of two kinds of source:</p><ul><li>an <strong>allocated</strong> start you set in advance — an individual time, a class mass start, or an event mass start, with the most specific winning (the <a href="./../event-setup/start-times#which-start-time-wins-the-hierarchy">start-time hierarchy</a>); or</li><li>a <strong>punched</strong> start the competitor records on the day, from a Start unit (read off the card or from a radio Start control).</li></ul><p>When a competitor has <strong>both</strong>, the <em>punching-start override</em> decides which is used. It is <strong>not</strong> fixed: by default a punched start overrides the allocated one, but this is a setting — configured <strong>per event</strong> (copied from a new-event default) and overridable <strong>per competitor</strong> (so you can make the allocated time win, or force the punch to win, for one runner). With the override off, the allocated time wins and the punch is kept as a fallback; with it on, the punch wins and the allocated time is the fallback. When only one of the two exists, that one is used. See <a href="./../event-setup/start-times#punched-starts">Punched starts</a> for the full hierarchy.</p><p>Manager resolves all of this for you and shows a small source label (<em>individual</em>, <em>class</em>, <em>event</em>, or <em>punched</em>) wherever a start time appears, so you can see where each competitor&#39;s time came from. The resolution falls back through:</p><ol><li>A <strong>manual override</strong> you set on the <strong>Overrides</strong> tab — beats everything.</li><li>The <strong>effective start</strong> from the allocated/punched sources above.</li><li>A <strong>check punch</strong>, used only during a card download when nothing above has supplied a start. (A check punch is never gated by the punching-start override — it&#39;s a last resort, not a start punch.) If you&#39;ve <em>excluded</em> the check punch on the <strong>Overrides</strong> tab — which is what you&#39;d do on a card the runner forgot to clear, where the check is left over from a previous run — it&#39;s skipped here as though the card never carried one.</li><li><strong>None</strong> — as a final fallback the start is treated as zero, so race time equals the finish time and the competitor sorts to the bottom until you give them a real start.</li></ol><h2 id="which-source-wins-when-sources-disagree" tabindex="-1">Which source wins when sources disagree <a class="header-anchor" href="#which-source-wins-when-sources-disagree" aria-label="Permalink to &quot;Which source wins when sources disagree&quot;">​</a></h2><ul><li><strong>Card download beats radio punches.</strong> A provisional OK from a radio finish is replaced by the card result, whatever it turns out to be. The card is the record of truth.</li><li><strong>Punched vs allocated start is the organiser&#39;s call, not a fixed rule.</strong> When a competitor has both, the <a href="./../event-setup/start-times#punched-starts">punching-start override</a> — set per event, optionally per competitor — decides which is used. By default the punch wins, but you can flip it.</li><li><strong>A control&#39;s time offset applies to everything.</strong> If you correct a control&#39;s clock with a <a href="./../event-setup/controls-and-radio-controls#time-offset">Time Offset</a>, it&#39;s applied to every punch on that control — card and radio alike — and retrospectively, re-timing punches that already came in.</li></ul><h2 id="worked-examples" tabindex="-1">Worked examples <a class="header-anchor" href="#worked-examples" aria-label="Permalink to &quot;Worked examples&quot;">​</a></h2><p><strong>Finishes but forgets to punch the finish.</strong> The card has no finish punch, so the download evaluates to <strong>DNF</strong>. If they really did finish, override the finish time on the <strong>Overrides</strong> tab and the result becomes <strong>OK</strong>.</p><p><strong>Card download contradicts the radio punches.</strong> They show a provisional <strong>OK</strong> from a radio finish, but the card is missing a control. The download wins: the status becomes <strong>MP</strong> and the provisional OK disappears from the official results.</p><p><strong>Allocated morning start but no punch all day.</strong> The start-time timer flips them to <strong>On Course</strong> when their start passes, and they sit there all day because no finish ever arrives. At wrap-up, confirm they never started and sweep them to <strong>DNS</strong>. See <a href="./../running-the-event/resolving-issues">Resolving issues on the day</a>.</p><p><strong>Relay leg missing a punch.</strong> The leg is evaluated against its course like any other card, so a missing required control gives that leg <strong>MP</strong>. Fix it the same way — override the punch if it&#39;s a genuine equipment miss.</p><h2 id="how-results-are-ordered" tabindex="-1">How results are ordered <a class="header-anchor" href="#how-results-are-ordered" aria-label="Permalink to &quot;How results are ordered&quot;">​</a></h2><p>Within a class, competitors sort best-to-worst by status group — <strong>OK</strong>, then <strong>On Course</strong>, then <em>None</em>, then the non-finishing statuses (Overtime, NoTiming, MP, DSQ, DNF, DNS, NP, OOC, Cancelled). Within <strong>OK</strong> they sort by race time, fastest first; <strong>On Course</strong> runners sort by projected finish time; equal times share a position and the next position is skipped accordingly.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../event-setup/start-times">Start times</a> — fixing a wrong or missing start</li><li><a href="./../running-the-event/card-download">Downloading cards</a> — the download evaluation and detail dialog</li><li><a href="./../running-the-event/resolving-issues">Resolving issues on the day</a> — symptom-to-fix recipes for wrong statuses and times</li><li><a href="./../running-the-event/safety-check">Safety check: accounting for everyone</a> — the On Course list and the DNS sweep</li><li><a href="./../running-the-event/station-memory">Station Memory</a> — recovering punches from a control&#39;s backup memory</li></ul>',64)])])}const m=e(a,[["render",n]]);export{g as __pageData,m as default};
